          type: 'craps-result', rarity: 'rare', icon: ICONS.crapsAutobattle, glyph: null,
          label,
          value: `+${_tokenText(amount)} FLIP`,
          sub: payoutCount > 0
            ? `${payoutCount} BATTLE ${payoutCount === 1 ? 'PAYOUT' : 'PAYOUTS'}`
            : `${winCount} WINNING ${winCount === 1 ? 'BATTLE' : 'BATTLES'}`,
          crapsWinCount: winCount,
